const INTERNAL_DOMAINS = [
  "@auth.memecatch.internal",
  "@wallet.memecatch.internal",
  "@kakao.memecatch.internal",
];

/** Email namespaces reserved for identities generated by trusted providers. */
export function blockedPublicEmail(email: string): boolean {
  const normalized = email.trim().toLowerCase();
  return INTERNAL_DOMAINS.some((domain) => normalized.endsWith(domain));
}

export function isKakaoInternalEmail(email: string): boolean {
  return email.trim().toLowerCase().endsWith("@kakao.memecatch.internal");
}
